package com.agacostays.payment.producer;
import com.agacostays.payment.constants.KafkaTopicConstants; import com.agacostays.payment.event.*; import org.springframework.kafka.core.KafkaTemplate; import org.springframework.stereotype.Component;
@Component public class PaymentEventProducer { private final KafkaTemplate<String,Object> kafka; public PaymentEventProducer(KafkaTemplate<String,Object> k){this.kafka=k;} public void paymentSuccess(PaymentSuccessEvent e){kafka.send(KafkaTopicConstants.PAYMENT_SUCCESS,String.valueOf(e.paymentId()),e);} public void paymentFailed(PaymentFailedEvent e){kafka.send(KafkaTopicConstants.PAYMENT_FAILED,String.valueOf(e.paymentId()),e);} public void refundProcessed(RefundProcessedEvent e){kafka.send(KafkaTopicConstants.REFUND_PROCESSED,String.valueOf(e.refundId()),e);} public void refundFailed(RefundFailedEvent e){kafka.send(KafkaTopicConstants.REFUND_FAILED,String.valueOf(e.refundId()),e);} public void webhookReceived(PaymentWebhookReceivedEvent e){kafka.send(KafkaTopicConstants.WEBHOOK_RECEIVED,e.gatewayPaymentId(),e);} }
